def parse_pairs(lines):
    result = {}
    for line in lines:
        # Skip blank lines
        if not line or line.strip() == '':
            continue
        # Split on first '='
        if '=' not in line:
            raise ValueError("Missing '=' in line: " + line)
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        # Reject empty key
        if key == '':
            raise ValueError("Empty key in line: " + line)
        # Later duplicate keys win
        result[key] = value
    return result

