def summarize_usage(events):
    # Track max input/output per request_id
    max_per_request = {}

    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)

        # Reject negative counts
        if input_count < 0:
            raise ValueError("Negative input count is not allowed")
        if output_count < 0:
            raise ValueError("Negative output count is not allowed")

        # Track maximum per request
        if request_id not in max_per_request:
            max_per_request[request_id] = {'input': 0, 'output': 0}

        if input_count > max_per_request[request_id]['input']:
            max_per_request[request_id]['input'] = input_count
        if output_count > max_per_request[request_id]['output']:
            max_per_request[request_id]['output'] = output_count

    # Sum across all requests
    total_input = 0
    total_output = 0
    for info in max_per_request:
        total_input += max_per_request[info]['input']
        total_output += max_per_request[info]['output']

    return {'input': total_input, 'output': total_output}

